// ============================================================
// FITBYTE LEAD QUALIFICATION BOT — COMPLETE CONVERSATION LOGIC
// ============================================================
// All session state is stored in workflow static data.
// Each Telegram message triggers this node once.
// This node figures out where the user is, responds, and saves state.
// ============================================================

const msg = $input.item.json.message;
if (!msg || !msg.text) {
  // Ignore non-text messages silently
  return { action: 'ignore' };
}

const chatId = String(msg.chat.id);
const userId = String(msg.from.id);
const text = msg.text.trim();
const firstName = msg.from.first_name || 'there';

// ------ SESSION STORAGE ------
// Use workflow static data as a simple key-value store.
// Key format: session_{userId}
// Value: JSON string of session object
const store = $getWorkflowStaticData('global');
const sessionKey = 'session_' + userId;

let session;
try {
  const raw = store[sessionKey];
  session = raw ? JSON.parse(raw) : null;
} catch(e) {
  session = null;
}

// If no session or user typed /start, reset
if (!session || text === '/start') {
  session = {
    step: 1,
    chatId: chatId,
    userId: userId,
    firstName: firstName,
    answers: []
  };
  store[sessionKey] = JSON.stringify(session);

  return {
    action: 'send_message',
    chatId: chatId,
    text: 'Hi ' + firstName + '! 👋 I\'m FitByte\'s fitness advisor.\n\nI\'ll match you with the perfect gear in 3 quick questions!\n\n*Question 1 of 3* 🎯\nWhat is your main fitness goal?\n\n① Lose weight\n② Build muscle\n③ Track performance\n④ General wellness',
    parseMode: 'Markdown',
    nextStep: null
  };
}

// ------ STEP MACHINE ------
const step = session.step;

// STEP 1: Waiting for answer to Q1
if (step === 1) {
  session.answers.push({ q: 'Fitness goal', a: text });
  session.step = 2;
  store[sessionKey] = JSON.stringify(session);

  return {
    action: 'send_message',
    chatId: chatId,
    text: '*Question 2 of 3* ⌚\nHow do you prefer to track your workouts?\n\n① On my wrist (smartwatch style)\n② Minimal & discreet (ring)\n③ Chest strap for maximum precision',
    parseMode: 'Markdown',
    nextStep: null
  };
}

// STEP 2: Waiting for answer to Q2
if (step === 2) {
  session.answers.push({ q: 'Tracking preference', a: text });
  session.step = 3;
  store[sessionKey] = JSON.stringify(session);

  return {
    action: 'send_message',
    chatId: chatId,
    text: '*Question 3 of 3* 🏋️\nHow seriously do you train?\n\n① Casual (1–2x per week)\n② Regular (3–4x per week)\n③ Athlete (5+ per week or competition)',
    parseMode: 'Markdown',
    nextStep: null
  };
}

// STEP 3: Waiting for answer to Q3
if (step === 3) {
  session.answers.push({ q: 'Training intensity', a: text });
  session.step = 4;
  store[sessionKey] = JSON.stringify(session);

  return {
    action: 'send_message',
    chatId: chatId,
    text: 'Almost there! 😊\n\nWhat is your *name*?',
    parseMode: 'Markdown',
    nextStep: null
  };
}

// STEP 4: Waiting for name
if (step === 4) {
  session.name = text;
  session.step = 5;
  store[sessionKey] = JSON.stringify(session);

  return {
    action: 'send_message',
    chatId: chatId,
    text: 'And your *email address* so our team can reach you? 📧',
    parseMode: 'Markdown',
    nextStep: null
  };
}

// STEP 5: Waiting for email
if (step === 5) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(text)) {
    // Invalid email — stay on step 5, ask again
    return {
      action: 'send_message',
      chatId: chatId,
      text: 'Hmm, that doesn\'t look like a valid email. 🤔\nCould you try again? (e.g. name@example.com)',
      parseMode: 'Markdown',
      nextStep: null
    };
  }

  session.email = text;
  session.step = 6;
  store[sessionKey] = JSON.stringify(session);

  // Return data for OpenAI classification + Notion routing
  return {
    action: 'classify',
    chatId: chatId,
    userId: userId,
    name: session.name,
    email: session.email,
    answer1: session.answers[0] ? session.answers[0].a : '',
    answer2: session.answers[1] ? session.answers[1].a : '',
    answer3: session.answers[2] ? session.answers[2].a : '',
    sessionKey: sessionKey
  };
}

// STEP 6+: Already completed
return {
  action: 'send_message',
  chatId: chatId,
  text: 'You have already completed the quiz! 🎉\nType /start to begin again.',
  parseMode: 'Markdown',
  nextStep: null
};

