// Parse OpenAI response and merge with lead data from previous node
const rawClassification = ($json.message?.content || '').trim().toUpperCase().replace(/[^A-Z]/g, '');
const valid = ['WATCH', 'RING', 'CHESTBAND'];
const product = valid.includes(rawClassification) ? rawClassification : 'WATCH';

// Get lead data from the Classify Or Send node (2 steps back)
const leadData = $('Classify or Send?').item.json;

return {
  product,
  chatId: leadData.chatId,
  userId: leadData.userId,
  name: leadData.name,
  email: leadData.email,
  answer1: leadData.answer1,
  answer2: leadData.answer2,
  answer3: leadData.answer3,
  sessionKey: leadData.sessionKey,
  timestamp: new Date().toISOString(),
  source: 'Telegram — FitByte Social Campaign'
};

// Clear session and prepare confirmation message
const store = $getWorkflowStaticData('global');
const sessionKey = $('Parse Product').item.json.sessionKey;
if (sessionKey && store[sessionKey]) {
  delete store[sessionKey];
}

const lead = $('Parse Product').item.json;
return {
  chatId: lead.chatId,
  name: lead.name,
  email: lead.email,
  product: lead.product
};
